export const portfolioMarkup = "<a class=\"skip-link\" href=\"#main\">Skip to content</a>\n<header class=\"topbar\" id=\"topbar\">\n  <nav class=\"nav-inner\" aria-label=\"Main navigation\">\n    <a class=\"brand\" href=\"#home\" aria-label=\"Abhishek Kumar Gautam, home\"><span class=\"brand-mark\">AG</span><span>Abhishek Kumar Gautam</span></a>\n    <div class=\"nav-links\" id=\"desktop-nav\">\n      <a href=\"#home\">Home</a><a href=\"#about\">About</a><a href=\"#skills\">Skills</a><a href=\"#projects\">Projects</a><a href=\"#uiux\">UI/UX</a><a href=\"#journey\">Journey</a><a href=\"#contact\">Contact</a>\n      <a class=\"nav-cta\" href=\"#\" data-resume-download>Download Resume <span aria-hidden=\"true\">&#8599;</span></a>\n    </div>\n    <button class=\"menu-toggle\" id=\"menu-toggle\" type=\"button\" aria-label=\"Open navigation menu\" aria-expanded=\"false\" aria-controls=\"mobile-menu\"><span></span></button>\n    <div class=\"mobile-menu\" id=\"mobile-menu\" hidden>\n      <a href=\"#home\">Home</a><a href=\"#about\">About</a><a href=\"#skills\">Skills</a><a href=\"#projects\">Projects</a><a href=\"#uiux\">UI/UX</a><a href=\"#journey\">Journey</a><a href=\"#contact\">Contact</a>\n      <a class=\"mobile-download\" href=\"#\" data-resume-download>Download Resume</a>\n    </div>\n  </nav>\n</header>\n<main id=\"main\">\n<section class=\"hero\" id=\"home\" aria-labelledby=\"hero-title\">\n    <div class=\"wrap hero-grid\">\n      <div class=\"hero-copy\">\n        <div class=\"overline\">Portfolio <span aria-hidden=\"true\">/</span> 2026</div>\n        <h1 id=\"hero-title\">Abhishek <span class=\"name-last\">Kumar Gautam</span></h1>\n        <p class=\"role-line\">Full-Stack Developer <span aria-hidden=\"true\">&middot;</span> UI/UX Designer <span aria-hidden=\"true\">&middot;</span> Cybersecurity Enthusiast</p>\n        <h2>Building digital experiences that feel simple, fast and meaningful.</h2>\n        <p class=\"hero-description\">Computer Science graduate focused on full-stack development, with project experience building responsive web applications using JavaScript, TypeScript, React.js, Next.js, Node.js and MongoDB. Project work includes API integrations, database-backed accounts and booking flows, testing and CI/CD, alongside foundational cybersecurity training. Seeking an entry-level software or full-stack developer role.</p>\n        <div class=\"hero-actions\">\n          <a class=\"button button-primary magnetic\" href=\"#projects\">View Projects <span class=\"arrow\" aria-hidden=\"true\">&#8599;</span></a>\n          <a class=\"button button-secondary magnetic\" href=\"#\" data-resume-download>Download Resume <span aria-hidden=\"true\">&#8595;</span></a>\n          <a class=\"text-link\" href=\"#\" data-resume-view>View Resume <span aria-hidden=\"true\">&#8599;</span></a>\n        </div>\n        <div class=\"hero-foot\"><span class=\"hero-foot-line\"></span><span>Greater Noida, Uttar Pradesh</span></div>\n      </div>\n      <figure class=\"portrait-stage\" id=\"portrait-stage\">\n        <div class=\"portrait-inner\"><img class=\"portrait\" src=\"/portrait.jpg\" alt=\"Professional portrait of Abhishek Kumar Gautam\" fetchpriority=\"high\"><figcaption class=\"portrait-caption\"><div><strong>Abhishek Kumar Gautam</strong><span>Computer Science</span></div><span class=\"portrait-index\">01 / AG</span></figcaption></div>\n      </figure>\n      <div class=\"hero-mobile-actions\"><a class=\"button button-primary\" href=\"#projects\">View Projects <span aria-hidden=\"true\">&#8599;</span></a><a class=\"button button-secondary\" href=\"#\" data-resume-download>Download Resume <span aria-hidden=\"true\">&#8595;</span></a><a class=\"text-link\" href=\"#\" data-resume-view>View Resume <span aria-hidden=\"true\">&#8599;</span></a></div>\n    </div>\n    <a class=\"scroll-mark\" href=\"#about\" aria-label=\"Scroll to About\">Scroll to explore</a>\n  </section>\n<div class=\"ticker\" aria-label=\"Portfolio focus areas\"><div class=\"ticker-inner wrap\"><span>Full-stack</span><span>Interfaces</span><span>Product thinking</span><span>Cybersecurity</span><span>Responsive design</span></div></div>\n<section id=\"about\" aria-labelledby=\"about-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">01 / About</span><div><h2 id=\"about-title\">More than<br><em>just code.</em></h2><p class=\"section-subtitle\">An engineering foundation, an eye for the interface, and a growing security perspective.</p></div></div>\n      <div class=\"about-grid\">\n        <p class=\"about-lead reveal\">A Computer Science graduate focused on building useful, responsive experiences from the interface down to the data behind it.</p>\n        <div class=\"reveal\"><p class=\"about-body\">The projects in my resume span full-stack movie discovery and ticket booking, reusable React interfaces, and an AI-powered chat application. They sit alongside UI/UX, Agile/Scrum, automated testing, CI/CD, and foundational cybersecurity training.</p><p class=\"about-body\">I bring those threads together here: clear structure, thoughtful interactions, and engineering details that are easy to explore.</p></div>\n      </div>\n      <div class=\"about-pillars stagger reveal\" aria-label=\"Portfolio themes\"><div class=\"pillar\"><span>01 / BUILD</span><strong>Full-stack</strong></div><div class=\"pillar\"><span>02 / SHAPE</span><strong>UI/UX</strong></div><div class=\"pillar\"><span>03 / PROTECT</span><strong>Cybersecurity</strong></div></div>\n    </div>\n  </section>\n<section id=\"skills\" aria-labelledby=\"skills-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">02 / Skills</span><div><h2 id=\"skills-title\">A practical<br><em>toolkit.</em></h2><p class=\"section-subtitle\">Grouped from the skills listed in my resume, from interface building to security fundamentals.</p></div></div>\n      <div class=\"skills-shell\">\n        <div class=\"skill-intro reveal\"><h3>Tools for the whole experience.</h3><p>Explore the areas I work across. Each card opens up through small, deliberate interactions.</p>\n          <div class=\"skill-filters\" role=\"group\" aria-label=\"Filter skill categories\"><button class=\"filter-btn\" type=\"button\" data-skill-filter=\"all\" aria-pressed=\"true\">All</button><button class=\"filter-btn\" type=\"button\" data-skill-filter=\"build\" aria-pressed=\"false\">Build</button><button class=\"filter-btn\" type=\"button\" data-skill-filter=\"design\" aria-pressed=\"false\">Design</button><button class=\"filter-btn\" type=\"button\" data-skill-filter=\"security\" aria-pressed=\"false\">Security</button></div>\n        </div>\n        <div class=\"skills-grid stagger reveal\" id=\"skills-grid\">\n          <article class=\"skill-card\" data-skill=\"design\"><span class=\"skill-icon\" aria-hidden=\"true\">UI</span><h3>Frontend &amp; UI/UX</h3><p>HTML5, CSS3, React.js, Next.js, Tailwind CSS, Redux Toolkit, Responsive Web Design, UI/UX</p></article>\n          <article class=\"skill-card\" data-skill=\"build\"><span class=\"skill-icon\" aria-hidden=\"true\">API</span><h3>Backend</h3><p>Node.js, Express.js, REST APIs, JWT Authentication, Role-Based Access Control (RBAC)</p></article>\n          <article class=\"skill-card\" data-skill=\"build\"><span class=\"skill-icon\" aria-hidden=\"true\">JS</span><h3>Programming &amp; Query Languages</h3><p>JavaScript, TypeScript, Java, C, C++, Python, SQL</p></article>\n          <article class=\"skill-card\" data-skill=\"build\"><span class=\"skill-icon\" aria-hidden=\"true\">DB</span><h3>Databases</h3><p>MongoDB, Oracle SQL, Database Design, Query Optimization</p></article>\n          <article class=\"skill-card\" data-skill=\"build\"><span class=\"skill-icon\" aria-hidden=\"true\">DEV</span><h3>Tools &amp; Practices</h3><p>Git, GitHub, Docker, GitHub Actions (CI/CD), Postman, Vercel, VS Code, Agile/Scrum, SDLC, Unit Testing, Debugging, Technical Documentation, Team Collaboration</p></article>\n          <article class=\"skill-card\" data-skill=\"security\"><span class=\"skill-icon\" aria-hidden=\"true\">SEC</span><h3>Cybersecurity</h3><p>Wireshark, Splunk, Threat Detection, Risk Analysis, Network Security</p></article>\n        </div>\n      </div>\n    </div>\n  </section>\n<section class=\"work-section\" id=\"projects\" aria-labelledby=\"projects-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head work-head reveal\"><span class=\"eyebrow\">03 / Selected work</span><div><h2 id=\"projects-title\">Built to be<br><em>experienced.</em></h2><p class=\"section-subtitle\">Three projects from my resume, with the features, engineering choices, and outcomes the source material supports.</p></div></div>\n      <div class=\"project-filters\" role=\"group\" aria-label=\"Filter projects\"><button class=\"filter-btn\" type=\"button\" data-project-filter=\"all\" aria-pressed=\"true\">All work</button><button class=\"filter-btn\" type=\"button\" data-project-filter=\"full-stack\" aria-pressed=\"false\">Full-stack</button><button class=\"filter-btn\" type=\"button\" data-project-filter=\"frontend\" aria-pressed=\"false\">Frontend</button></div>\n      <div class=\"project-grid\" id=\"project-grid\">\n        <article class=\"project-card featured reveal\" data-project=\"full-stack\" aria-labelledby=\"music-project-title\">\n          <div class=\"project-art\" aria-label=\"Abstract visual representing movie discovery and cinema seating\">\n            <span class=\"poster-mark\">MUSIC &amp; MOVIES SHOW</span>\n            <div class=\"cinema-art\"><div class=\"cinema-top\"><span>DISCOVERY / BOOKING</span><span>01</span></div><div class=\"cinema-title\">A story in every seat.</div><div class=\"cinema-sub\">Films, television, anime and cinema</div><div class=\"screen-bar\"></div><div class=\"seat-rows\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i></div></div>\n            <span class=\"poster-code\">2D / 3D</span>\n          </div>\n          <div class=\"project-copy\">\n            <div class=\"project-topline\"><span>Full-stack experience</span><span class=\"project-year\">Sep 2026</span></div>\n            <h3 id=\"music-project-title\">Music &amp; Movies Show</h3>\n            <p class=\"project-summary\">A responsive discovery and ticket-booking application for films, television, and anime, with a cinema experience spanning a 2D seat map and a sign-in-gated 3D theater.</p>\n            <ul class=\"feature-list\">\n              <li>TMDB discovery and trailers, with optional Spotify OAuth/API, OMDb enrichment, and YouTube fallback.</li>\n              <li>MongoDB-backed email/password sign-in, cookie sessions, saved favorites, viewing history, and confirmed bookings.</li>\n              <li>GitHub Actions checks, Vercel deployment, and API rate limiting at 120 requests per 60 seconds by default.</li>\n            </ul>\n            <div class=\"tech-row\" aria-label=\"Technologies\"><span class=\"tech-tag\">Next.js</span><span class=\"tech-tag\">TypeScript</span><span class=\"tech-tag\">MongoDB</span></div>\n            <div class=\"project-actions\"><a class=\"button button-primary button-small magnetic\" href=\"https://music-and-movies-show.vercel.app/\" target=\"_blank\" rel=\"noopener noreferrer\">Live Demo <span class=\"arrow\" aria-hidden=\"true\">&#8599;</span></a><a class=\"button button-secondary button-small\" href=\"https://github.com/Gautam215\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub profile <span class=\"arrow\" aria-hidden=\"true\">&#8599;</span></a></div>\n            <details class=\"case-study\"><summary>Explore the case study</summary><div class=\"case-body\"><div><strong>Overview</strong>Movie discovery and ticket booking for films, TV, and anime in a responsive web application.</div><div><strong>Experience</strong>2D seat-map booking, a sign-in-gated 3D theater with five curved rows, and trailers on the cinema screen.</div><div><strong>Engineering</strong>MongoDB-backed accounts and booking data, service integrations, CI checks, Vercel deployment, and configured request limits.</div></div></details>\n          </div>\n        </article>\n\n        <article class=\"project-card project-small reveal\" data-project=\"frontend\" aria-labelledby=\"campus-project-title\">\n          <div class=\"project-art portal-art\" aria-label=\"Abstract responsive website layout\"><span class=\"poster-mark\">CAMPUS CONNECT</span><div class=\"portal-window\"><div class=\"window-dots\"><i></i><i></i><i></i></div><div class=\"portal-header\"></div><div class=\"portal-subline\"></div><div class=\"portal-tiles\"><i></i><i></i><i></i><i></i></div></div><span class=\"poster-code\">REACT / CSS</span></div>\n          <div class=\"project-copy\"><div class=\"project-topline\"><span>Frontend</span><span class=\"project-year\">Jul 2024</span></div><h3 id=\"campus-project-title\">Campus Connect Portal</h3><p class=\"project-summary\">A responsive college website built with an Agile team using React.js and modular CSS.</p><ul class=\"feature-list\"><li>Reusable React components for navigation and page transitions.</li><li>Tested and deployed on Vercel.</li></ul><div class=\"tech-row\"><span class=\"tech-tag\">React.js</span><span class=\"tech-tag\">Modular CSS</span><span class=\"tech-tag\">Vercel</span></div><details class=\"case-study\"><summary>Build notes</summary><div class=\"case-body\"><div><strong>Collaboration</strong>Built with an Agile team.</div><div><strong>Interface</strong>Responsive college website with reusable navigation and page-transition components.</div><div><strong>Outcome</strong>Tested and deployed on Vercel.</div></div></details></div>\n        </article>\n\n        <article class=\"project-card project-small reveal\" data-project=\"frontend\" aria-labelledby=\"chatbot-project-title\">\n          <div class=\"project-art chat-art\" aria-label=\"Abstract responsive chat interface\"><span class=\"poster-mark\">SMART CHATBOT</span><div class=\"chat-window\"><div class=\"window-dots\"><i></i><i></i><i></i></div><div class=\"chat-line\"></div><div class=\"chat-line short\"></div><div class=\"chat-line user\"></div><div class=\"chat-line\"></div><div class=\"chat-line short\"></div><div class=\"chat-entry\"></div></div><span class=\"poster-code\">STATE / HISTORY</span></div>\n          <div class=\"project-copy\"><div class=\"project-topline\"><span>Frontend</span><span class=\"project-year\">Mar 2023</span></div><h3 id=\"chatbot-project-title\">Smart Chatbot</h3><p class=\"project-summary\">An AI-powered chat application created collaboratively, with an interface designed for multiple screen sizes.</p><ul class=\"feature-list\"><li>Responsive interface for varied screen sizes.</li><li>Redux Toolkit manages chat history, application state, and data flow.</li></ul><div class=\"tech-row\"><span class=\"tech-tag\">React.js</span><span class=\"tech-tag\">Modular CSS</span><span class=\"tech-tag\">Redux Toolkit</span></div><details class=\"case-study\"><summary>Build notes</summary><div class=\"case-body\"><div><strong>Collaboration</strong>Built with a team.</div><div><strong>Interface</strong>Responsive chat application interface.</div><div><strong>State</strong>Redux Toolkit organizes chat history and application data flow.</div></div></details></div>\n        </article>\n      </div>\n    </div>\n  </section>\n<section id=\"uiux\" aria-labelledby=\"uiux-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">04 / UI &amp; UX</span><div><h2 id=\"uiux-title\">Interfaces with<br><em>intention.</em></h2><p class=\"section-subtitle\">A small interactive gallery of responsive patterns and interface details in this portfolio. Swipe or scroll horizontally to explore.</p></div></div>\n      <div class=\"showcase-track reveal\" aria-label=\"Horizontal UI and UX showcase\">\n        <article class=\"showcase-card\"><span class=\"showcase-label\">01 / Hierarchy</span><h3>One clear next step.</h3><p>Type, spacing and contrast guide the eye.</p><div class=\"showcase-ui\"><div class=\"mini-nav\"><span>AG / PORTFOLIO</span><span>Selected work</span></div><div class=\"mini-title\"></div><div class=\"mini-copy\"></div><div class=\"mini-copy\" style=\"width:55%\"></div><div class=\"mini-cards\"><i></i><i></i></div></div></article>\n        <article class=\"showcase-card\"><span class=\"showcase-label\">02 / Responsive</span><h3>Comfortable at every width.</h3><p>The page reorganizes rather than simply shrinking.</p><div class=\"showcase-ui\"><div class=\"mini-nav\"><span>ABHISHEK GAUTAM</span><span>Menu</span></div><div class=\"mini-title\" style=\"width:48%\"></div><div class=\"mini-copy\" style=\"width:84%\"></div><div class=\"mini-cards\"><i></i><i></i></div></div></article>\n        <article class=\"showcase-card\"><span class=\"showcase-label\">03 / Interaction</span><h3>Quiet feedback.</h3><p>Focus, hover and pressed states stay deliberate.</p><div class=\"showcase-ui\"><div class=\"mini-nav\"><span>DESIGN PLAYGROUND</span><span>Active</span></div><div class=\"mini-title\" style=\"width:42%\"></div><div class=\"mini-copy\" style=\"width:72%\"></div><div class=\"mini-cards\"><i></i><i></i></div></div></article>\n      </div>\n    </div>\n  </section>\n<section id=\"figma-code\" aria-labelledby=\"figma-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">05 / From Figma to Code</span><div><h2 id=\"figma-title\">Think in systems.<br><em>Build with care.</em></h2><p class=\"section-subtitle\">A design direction becomes useful when its hierarchy, spacing, responsive rules, and interaction states carry through into reusable interface components.</p></div></div>\n      <div class=\"figma-grid reveal\">\n        <article class=\"flow-panel\"><span class=\"eyebrow\">Design / Structure</span><h3>Start with the hierarchy.</h3><p>Establish a visual rhythm, define a small set of tokens, and make the next action easy to find.</p><div class=\"flow-steps\"><span>Type</span><b>&rarr;</b><span>Space</span><b>&rarr;</b><span>States</span></div><div class=\"design-sheet\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></div></article>\n        <article class=\"flow-panel code-panel\"><span class=\"eyebrow\">Code / Components</span><h3>Then make it responsive.</h3><p>The interactive examples on this page show the same system in buttons, cards, controls, and layouts.</p><div class=\"code-preview\" aria-label=\"Illustrative component code\"><span class=\"kw\">&lt;section</span> <span class=\"prop\">className</span>=<span class=\"str\">\"project-card\"</span><span class=\"kw\">&gt;</span><br>&nbsp;&nbsp;<span class=\"kw\">&lt;ProjectSummary</span> /&gt;<br>&nbsp;&nbsp;<span class=\"kw\">&lt;TechTags</span> items={stack} /&gt;<br>&nbsp;&nbsp;<span class=\"kw\">&lt;ActionLink</span> href={liveDemo} /&gt;<br><span class=\"kw\">&lt;/section&gt;</span></div></article>\n      </div>\n    </div>\n  </section>\n<section id=\"design-system\" aria-labelledby=\"system-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">06 / Design system</span><div><h2 id=\"system-title\">Small rules.<br><em>Coherent details.</em></h2><p class=\"section-subtitle\">A compact set of visual tokens and live controls used across this portfolio.</p></div></div>\n      <div class=\"token-board stagger reveal\" aria-label=\"Portfolio color tokens\">\n        <div class=\"token\"><div class=\"token-swatch\" style=\"background:#090a0b\"></div><strong>Canvas</strong><span>#090A0B</span></div>\n        <div class=\"token\"><div class=\"token-swatch\" style=\"background:#111315\"></div><strong>Surface</strong><span>#111315</span></div>\n        <div class=\"token\"><div class=\"token-swatch\" style=\"background:#f4f5f7\"></div><strong>Type</strong><span>#F4F5F7</span></div>\n        <div class=\"token\"><div class=\"token-swatch\" style=\"background:#c8c0e7\"></div><strong>Accent</strong><span>#C8C0E7</span></div>\n      </div>\n      <div class=\"token-demo reveal\"><span class=\"tech-tag\">SF Pro / system</span><span class=\"tech-tag\">12-column rhythm</span><span class=\"tech-tag\">Soft borders</span><span class=\"tech-tag\">Reduced motion</span><button class=\"demo-mini\" type=\"button\" data-toast=\"Button state is active\">Button state</button><input type=\"text\" aria-label=\"Example design-system input\" placeholder=\"Focus the input to see its state\"></div>\n    </div>\n  </section>\n<section id=\"ux-log\" aria-labelledby=\"ux-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">07 / UX decision log</span><div><h2 id=\"ux-title\">Every detail<br><em>has a reason.</em></h2><p class=\"section-subtitle\">A few choices behind this portfolio interface. Open a note to see the reasoning.</p></div></div>\n      <div class=\"decision-grid stagger reveal\">\n        <details class=\"decision\"><summary>Why this navigation?</summary><p>Section links stay visible on wide screens, while the compact mobile menu preserves the same destinations without crowding the page.</p></details>\n        <details class=\"decision\"><summary>Why this content order?</summary><p>About, skills, and selected work appear early so visitors can understand the profile and projects before exploring the design playground.</p></details>\n        <details class=\"decision\"><summary>Why one accent color?</summary><p>A restrained accent marks selected states and small cues without competing with the photo or project content.</p></details>\n        <details class=\"decision\"><summary>Why this responsive behavior?</summary><p>Columns collapse into a reading-first mobile flow, with controls enlarged and horizontal galleries kept swipeable.</p></details>\n      </div>\n    </div>\n  </section>\n<section id=\"before-after\" aria-labelledby=\"compare-title\">\n    <div class=\"wrap compare-shell\">\n      <div class=\"compare-copy reveal\"><span class=\"eyebrow\">08 / Before &amp; after</span><h3 id=\"compare-title\">A little more<br>visual clarity.</h3><p>Drag the control to compare a loose content arrangement with a more considered hierarchy. This is a layout study created for this portfolio.</p><label class=\"state-label\" for=\"compare-control\">Use arrow keys or drag to compare</label></div>\n      <div class=\"compare-stage reveal\" id=\"compare-stage\" style=\"--split:54%\">\n        <span class=\"compare-label before\">Before</span><span class=\"compare-label after\">After</span>\n        <div class=\"compare-layer compare-after\"><div class=\"compare-surface\"><div><i></i><i></i><i></i><i></i></div><span class=\"sample-block\"></span></div></div>\n        <div class=\"compare-layer compare-before\"><div class=\"compare-surface\"><div><i></i><i></i><i></i><i></i></div><span class=\"sample-block\"></span></div></div>\n        <span class=\"compare-divider\" aria-hidden=\"true\"></span>\n        <input class=\"compare-control\" type=\"range\" id=\"compare-control\" min=\"15\" max=\"85\" value=\"54\" aria-label=\"Drag to compare Before and After layout\">\n      </div>\n    </div>\n  </section>\n<section id=\"journey\" aria-labelledby=\"journey-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">09 / Journey</span><div><h2 id=\"journey-title\">Learning by<br><em>building.</em></h2><p class=\"section-subtitle\">A timeline of education and projects, using the dates shown in my resume.</p></div></div>\n      <ol class=\"timeline reveal\">\n        <li class=\"timeline-item\"><span class=\"timeline-date\">Aug 2020<br>May 2022</span><span class=\"timeline-dot\" aria-hidden=\"true\"></span><div><h3>Senior Secondary Education</h3><p>Sri Chaitanya Techno School, Visakhapatnam, Andhra Pradesh &middot; Class XII, PCM</p></div></li>\n        <li class=\"timeline-item\"><span class=\"timeline-date\">Oct 2022<br>Aug 2026</span><span class=\"timeline-dot\" aria-hidden=\"true\"></span><div><h3>Bachelor of Technology in Computer Science</h3><p>Galgotias University, Greater Noida, Uttar Pradesh</p></div></li>\n        <li class=\"timeline-item\"><span class=\"timeline-date\">Mar 2023</span><span class=\"timeline-dot\" aria-hidden=\"true\"></span><div><h3>Smart Chatbot</h3><p>AI-powered chat application; responsive interface and Redux Toolkit-managed chat history.</p></div></li>\n        <li class=\"timeline-item\"><span class=\"timeline-date\">Jul 2024</span><span class=\"timeline-dot\" aria-hidden=\"true\"></span><div><h3>Campus Connect Portal</h3><p>Responsive college website with reusable navigation and page-transition components.</p></div></li>\n        <li class=\"timeline-item\"><span class=\"timeline-date\">Sep 2026</span><span class=\"timeline-dot\" aria-hidden=\"true\"></span><div><h3>Music &amp; Movies Show</h3><p>Responsive discovery and ticket booking, with a 2D seat map and a sign-in-gated 3D theater.</p></div></li>\n      </ol>\n      <div class=\"education-grid stagger reveal\">\n        <article class=\"education-card\"><span class=\"eyebrow\">Education / 01</span><h3>Galgotias University</h3><p>Bachelor of Technology in Computer Science<br>Greater Noida, Uttar Pradesh</p><span class=\"date\">Oct 2022 &mdash; Aug 2026</span></article>\n        <article class=\"education-card\"><span class=\"eyebrow\">Education / 02</span><h3>Sri Chaitanya Techno School</h3><p>Senior Secondary Education (Class XII, PCM)<br>Visakhapatnam, Andhra Pradesh</p><span class=\"date\">Aug 2020 &mdash; May 2022</span></article>\n      </div>\n      <div class=\"education-card reveal\" style=\"margin-top:13px\"><span class=\"eyebrow\">Leadership / Mar 2023</span><h3>Campus Ambassador &middot; Tryst '23, IIT Delhi</h3><p>Ranked #1 among all campus ambassadors nationwide for Tryst '23; led the points leaderboard by driving the highest event participation.</p></div>\n      <div class=\"language-strip reveal\" aria-label=\"Languages spoken\"><span>Hindi <i>Native</i></span><span>English <i>Conversational</i></span><span>French <i>Beginner</i></span></div>\n    </div>\n  </section>\n<section id=\"cybersecurity\" aria-labelledby=\"security-title\">\n    <div class=\"wrap\">\n      <div class=\"section-head reveal\"><span class=\"eyebrow\">10 / Cybersecurity</span><div><h2 id=\"security-title\">A thoughtful<br><em>security lens.</em></h2><p class=\"section-subtitle\">Security skills and training listed in my resume, presented as a complement to full-stack development.</p></div></div>\n      <div class=\"security-panel reveal\">\n        <div><div class=\"security-mark\" aria-hidden=\"true\">&#9671;</div><h3>Curious about what sits beneath the surface.</h3><p>My resume pairs cybersecurity training with tools and practices spanning threat detection, risk analysis, and network security.</p></div>\n        <div><div class=\"security-list\"><div class=\"security-item\">Wireshark</div><div class=\"security-item\">Splunk</div><div class=\"security-item\">Threat Detection</div><div class=\"security-item\">Risk Analysis</div><div class=\"security-item\">Network Security</div></div></div>\n      </div>\n      <div class=\"cert-list stagger reveal\" aria-label=\"Certifications and training\">\n        <div class=\"cert-item\">Cyber Job Simulation, Deloitte Australia (via Forage)<span>Jul 2026</span></div>\n        <div class=\"cert-item\">Master Mentors Geo-Enabling Indian Scholars (MMGEIS)<span>Mar 2026</span></div>\n        <div class=\"cert-item\">Cyber Security, Prodigy Infotech<span>Dec 2025</span></div>\n        <div class=\"cert-item\">Postman API Fundamentals<span>Feb 2025</span></div>\n        <div class=\"cert-item\">Oracle Java Fundamentals<span>Dec 2024</span></div>\n        <div class=\"cert-item\">Oracle Database Programming with SQL<span>Jan 2024</span></div>\n      </div>\n    </div>\n  </section>\n<section id=\"playground\" aria-labelledby=\"playground-title\">\n    <div class=\"wrap playground-shell\">\n      <div class=\"playground-copy reveal\"><span class=\"eyebrow\">11 / Design Playground</span><h3 id=\"playground-title\">Small things.<br>Made tangible.</h3><p>Real controls, states, and feedback. Try a toggle, switch tabs, open a modal, or focus the input.</p><div class=\"tech-row\"><span class=\"tech-tag\">Buttons</span><span class=\"tech-tag\">Inputs</span><span class=\"tech-tag\">Tabs</span><span class=\"tech-tag\">Feedback</span></div></div>\n      <div class=\"playground reveal\" id=\"playground-demo\">\n        <div class=\"playground-head\"><div><strong>Interaction lab</strong><div class=\"state-label\" id=\"play-state\" aria-live=\"polite\">Components / ready</div></div><div class=\"play-tabs\" role=\"tablist\" aria-label=\"Playground component set\"><button class=\"play-tab\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-play-tab=\"components\">Components</button><button class=\"play-tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-play-tab=\"states\">States</button></div></div>\n        <div class=\"playground-grid\">\n          <div class=\"demo-control\" data-demo-panel=\"components\"><span class=\"demo-caption\">Button / hover</span><div class=\"demo-row\"><button class=\"demo-mini\" type=\"button\" data-toast=\"The button is ready\">Try button</button><span class=\"demo-pill\">Quiet feedback</span></div></div>\n          <div class=\"demo-control\" data-demo-panel=\"components\"><label for=\"play-input\">Input / focus</label><input class=\"demo-input\" id=\"play-input\" type=\"text\" placeholder=\"Type a note\"></div>\n          <div class=\"demo-control\" data-demo-panel=\"components\"><span class=\"demo-caption\">Toggle / state</span><div class=\"demo-row\"><button class=\"toggle\" type=\"button\" role=\"switch\" aria-checked=\"false\" aria-label=\"Toggle sample state\" id=\"sample-toggle\"></button><span class=\"demo-pill\" id=\"toggle-label\">Off</span></div></div>\n          <div class=\"demo-control\" data-demo-panel=\"components\"><label for=\"play-select\">Dropdown / select</label><select class=\"demo-input\" id=\"play-select\"><option>Choose a surface</option><option>Card</option><option>Navigation</option><option>Modal</option></select></div>\n          <div class=\"demo-control\" data-demo-panel=\"states\"><span class=\"demo-caption\">Modal / open</span><button class=\"demo-mini\" type=\"button\" id=\"open-modal\">Open details</button></div>\n          <div class=\"demo-control\" data-demo-panel=\"states\"><span class=\"demo-caption\">Tooltip / hover or focus</span><div class=\"demo-row\"><button class=\"demo-mini\" type=\"button\" title=\"A small hint, right on time.\">Hover for a hint</button></div></div>\n          <div class=\"demo-control\" data-demo-panel=\"states\"><span class=\"demo-caption\">Loading / skeleton</span><div class=\"skeleton\"></div><div class=\"skeleton short\"></div></div>\n          <div class=\"demo-control\" data-demo-panel=\"states\"><span class=\"demo-caption\">Navigation / active</span><div class=\"demo-row\"><span class=\"demo-pill\" style=\"border-color:rgba(200,192,231,.6);color:#e7e1f6\">Projects</span><span class=\"demo-pill\">About</span></div></div>\n        </div>\n      </div>\n    </div>\n  </section>\n<section id=\"contact\" aria-labelledby=\"contact-title\">\n    <div class=\"wrap\">\n      <div class=\"contact-panel reveal\">\n        <div><span class=\"eyebrow\">12 / Contact</span><h2 id=\"contact-title\">Let's build something meaningful.</h2><p>For conversations about software, interfaces, and engineering, reach out directly or send a message from your email app.</p>\n          <div class=\"contact-links\"><a href=\"mailto:ak9724068@gmail.com\">ak9724068@gmail.com <span aria-hidden=\"true\">&#8599;</span></a><a href=\"tel:+919234950604\">+91 9234950604 <span aria-hidden=\"true\">&#8599;</span></a><a href=\"https://github.com/Gautam215\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub <span aria-hidden=\"true\">&#8599;</span></a><a href=\"https://linkedin.com/in/gautam313\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn <span aria-hidden=\"true\">&#8599;</span></a></div>\n        </div>\n        <form class=\"contact-form\" id=\"contact-form\">\n          <div class=\"form-row\"><div class=\"field\"><label for=\"contact-name\">Name</label><input id=\"contact-name\" name=\"name\" autocomplete=\"name\" required placeholder=\"Your name\"></div><div class=\"field\"><label for=\"contact-email\">Email</label><input id=\"contact-email\" name=\"email\" type=\"email\" autocomplete=\"email\" required placeholder=\"you@example.com\"></div></div>\n          <div class=\"field\"><label for=\"contact-message\">Message</label><textarea id=\"contact-message\" name=\"message\" required placeholder=\"What would you like to build?\"></textarea></div>\n          <div class=\"demo-row\"><button class=\"button button-primary magnetic\" type=\"submit\">Send <span class=\"arrow\" aria-hidden=\"true\">&#8599;</span></button><a class=\"button button-secondary button-small\" href=\"#\" data-resume-download>Download Resume <span aria-hidden=\"true\">&#8595;</span></a><a class=\"text-link\" href=\"#\" data-resume-view>View Resume</a></div>\n          <p class=\"form-status\" id=\"form-status\" role=\"status\" aria-live=\"polite\"></p>\n        </form>\n      </div>\n    </div>\n  </section>\n</main>\n<footer class=\"footer\"><div class=\"wrap footer-inner\"><span>&copy; 2026 Abhishek Kumar Gautam</span><nav class=\"footer-links\" aria-label=\"Footer links\"><a href=\"https://github.com/Gautam215\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub</a><a href=\"https://linkedin.com/in/gautam313\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn</a><a href=\"mailto:ak9724068@gmail.com\">Email</a><a href=\"#\" data-resume-download>Resume</a><a href=\"#\" data-resume-view>View PDF</a></nav></div></footer>\n<div class=\"modal-backdrop\" id=\"demo-modal\" hidden role=\"presentation\"><div class=\"modal-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modal-title\" aria-describedby=\"modal-copy\"><h3 id=\"modal-title\">A detail, made clear.</h3><p id=\"modal-copy\">This modal demonstrates a focused action state: one message, one close action, and a clear way back to the page.</p><button class=\"button button-secondary button-small\" type=\"button\" id=\"close-modal\">Close</button></div></div>\n<div class=\"cursor-dot\" aria-hidden=\"true\"></div><div class=\"cursor-ring\" aria-hidden=\"true\"></div>\n<div class=\"sr-only\" id=\"toast-status\" role=\"status\" aria-live=\"polite\"></div>";
